// Fechas: el servidor las envía en SU hora local. TZO = desfase entre el servidor y este dispositivo (se calcula con /api/info),
// así «hace 5 minutos» es correcto aunque el hosting esté en otra zona horaria o el reloj del celular esté movido.
let TZO=0,TZR=0;const dtx=(s,o)=>{const x=String(s);return /Z$|[+-]\d\d:?\d\d$/.test(x)?new Date(x):new Date(new Date(x.replace(" ","T")).getTime()+o)},dts=s=>dtx(s,TZR); // TZO exacto para «hace X»; TZR (múltiplo de 15 min) para horas de reloj
const ago=s=>{const d=(Date.now()-dtx(s,TZO))/6e4;if(!(d>=-2))return"—";const u=d<60?[d,"minuto","minute"]:d<1440?[d/60,"hora","hour"]:d<43200?[d/1440,"día","day"]:[d/43200,"mes","month"],n=Math.max(1,Math.floor(u[0]));return L==="en"?`${n} ${u[2]}${n>1?"s":""} ago`:`hace ${n} ${u[1]}${n>1?(u[1]==="mes"?"es":"s"):""}`};
