const PVC={};async function pvFill(el){const u=el.dataset.pv;if(!u)return;el.removeAttribute("data-pv");const o=await(PVC[u]||(PVC[u]=api("/preview?u="+encodeURIComponent(u)).then(r=>r.ok?r.d:{})));if(!o||!o.title)return;el.innerHTML=`${o.img?`<img src="${esc(o.img)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">`:""}<span><small>${esc(o.host||"")}</small><b>${esc(o.title)}</b>${o.descr?`<em>${esc(o.descr)}</em>`:""}</span>`;el.hidden=false}
if("IntersectionObserver"in window&&"MutationObserver"in window){const pio=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){pio.unobserve(e.target);pvFill(e.target)}}),{rootMargin:"500px 0px"});new MutationObserver(()=>document.querySelectorAll("a.lp[data-pv]:not([data-w])").forEach(el=>{el.dataset.w=1;pio.observe(el)})).observe(document.body,{childList:true,subtree:true})}
function paintBadge(){document.querySelectorAll(".nb").forEach(b=>{const v=b.classList.contains("mb")?MM:NN;b.textContent=v>99?"99+":String(v);b.hidden=!(U&&v>0)})}
async function pollN(){clearTimeout(nTm);if(!U)return;if(!document.hidden){const r=await api("/notifications/count");if(r.ok){const n=Number(r.d.n)||0,more=n>NN;NN=n;MM=Number(r.d.m)||0;paintBadge();if(more&&view==="notif"&&!$("#mod.on"))show()}}nTm=setTimeout(pollN,LIVE?120000:30000)} // con la conexión en vivo el sondeo es solo un respaldo
// En vivo: el servidor avisa al instante (notificaciones, mensajes, «escribiendo», «visto»). Si falla, sigue el sondeo normal.
let ES=null,LIVE=false;
function live(){if(!U||!("EventSource"in window)||ES||document.hidden)return;try{ES=new EventSource("/api/stream")}catch{return}
 ES.onopen=()=>{LIVE=true};ES.onerror=()=>{LIVE=false;if(ES&&ES.readyState===2)ES=null};
 ES.addEventListener("notif",()=>pollN());
 for(const ev of["msg","typing","seen","rx","del"])ES.addEventListener(ev,e=>{let d={};try{d=JSON.parse(e.data)}catch{}if(window.onLive)window.onLive(ev,d);if(ev==="msg")pollN()})}
function liveOff(){if(ES){ES.close();ES=null}LIVE=false}
document.addEventListener("visibilitychange",()=>{if(document.hidden)liveOff();else if(U){live();pollN()}}); // una pestaña oculta suelta la conexión
// Service worker (página sin conexión + notificaciones push)
if("serviceWorker"in navigator)addEventListener("load",()=>navigator.serviceWorker.register("/sw.js").catch(()=>{}));
const pushOk=()=>"serviceWorker"in navigator&&"PushManager"in window&&"Notification"in window;
async function pushSub(){if(!pushOk())return null;const reg=await navigator.serviceWorker.getRegistration();return reg?reg.pushManager.getSubscription():null}
async function pushOn(){if(!pushOk())return t("Este navegador no admite notificaciones push");const k=(await api("/push/key")).d.key;if(!k)return t("Las notificaciones push no están activas en el servidor");
 if(await Notification.requestPermission()!=="granted")return t("Tienes que permitir las notificaciones en el navegador");
 const reg=await navigator.serviceWorker.ready,sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(atob(k.replace(/-/g,"+").replace(/_/g,"/")),c=>c.charCodeAt(0))}),j=sub.toJSON();
 const r=await api("/push/sub",{method:"POST",body:{endpoint:j.endpoint,keys:j.keys}});if(!r.ok){await sub.unsubscribe().catch(()=>{});return r.d.error||"Error"}return""}
async function pushOff(){const sub=await pushSub();if(!sub)return;await api("/push/sub",{method:"DELETE",body:{endpoint:sub.endpoint}});await sub.unsubscribe().catch(()=>{})}
