function mnClose(){clearTimeout(mnT);document.getElementById("mnl")?.remove()}
document.addEventListener("input",e=>{const el=e.target;if(!el.matches||!el.matches("[data-mn]"))return;const m=/(^|[^\w@])@(\w{2,24})$/.exec(el.value.slice(0,el.selectionStart==null?el.value.length:el.selectionStart));clearTimeout(mnT);if(!m)return mnClose();
 mnT=setTimeout(async()=>{const r=await api("/users/search?q="+encodeURIComponent(m[2]));if(!r.ok||!r.d.length||document.activeElement!==el)return mnClose();mnClose();
  const b=document.createElement("div"),rc=el.getBoundingClientRect();b.id="mnl";b.className="mnl";b.style.left=Math.max(4,rc.left)+"px";b.style.width=Math.min(rc.width,innerWidth-8)+"px";
  if(rc.top>innerHeight*.5)b.style.bottom=(innerHeight-rc.top+4)+"px";else b.style.top=(rc.bottom+4)+"px";
  b.innerHTML=r.d.map(x=>`<button type="button" data-n="${esc(x.name)}">${skin(x.skin,x.name)}<span>${nom(x.name)}</span></button>`).join("");
  b.onpointerdown=ev=>ev.preventDefault();
  b.onclick=ev=>{const bt=ev.target.closest("button[data-n]");if(!bt)return;const pos=el.selectionStart==null?el.value.length:el.selectionStart,pre=el.value.slice(0,pos).replace(/@\w*$/,"@"+bt.dataset.n+" "),post=el.value.slice(pos);el.value=pre+post;el.setSelectionRange(pre.length,pre.length);el.focus();el.dispatchEvent(new Event("input",{bubbles:true}));mnClose()};
  document.body.appendChild(b)},250)});
