function pfEdit(){const u=window.PFU||{};modal(`<h3>${t("Editar perfil")}</h3><div class="mm"><label class="btn">${ic("galeria")} ${t("Cambiar foto de perfil")}<input type="file" accept="image/*" hidden onchange="pfUp('avatar',this)"></label>${u.avatar?`<button class="btn" type="button" onclick="pfDel('avatar')">${t("Quitar foto de perfil")}</button>`:""}<label class="btn">${ic("galeria")} ${t("Cambiar banner")}<input type="file" accept="image/*" hidden onchange="pfUp('cover',this)"></label>${u.cover?`<button class="btn" type="button" onclick="pfDel('cover')">${t("Quitar banner")}</button>`:""}</div><label for="pfbi">${t("Biografía")}</label><textarea id="pfbi" rows="3" maxlength="160" placeholder="${t("Cuéntale a la comunidad algo sobre ti")}">${esc(u.bio||"")}</textarea><label for="pfci">${t("Ciudad")}</label><input id="pfci" maxlength="40" value="${esc(u.city||"")}"><label for="pfjo">${t("Ocupación")}</label><input id="pfjo" maxlength="60" value="${esc(u.job||"")}"><label for="pfli">${t("Enlace (https://…)")}</label><input id="pfli" maxlength="120" inputmode="url" value="${esc(u.link||"")}"><label for="pfbd">${t("Cumpleaños (DD/MM)")}</label><input id="pfbd" maxlength="5" inputmode="numeric" placeholder="DD/MM" value="${u.bday?esc(u.bday.slice(3)+"/"+u.bday.slice(0,2)):""}"><div class="msg" id="pfm" role="alert"></div><button class="btn p" type="button" onclick="pfBio()">${t("Guardar")}</button> <button class="btn" type="button" onclick="cerrar()">${t("Cerrar")}</button>`)}
