const pollHtml=p=>{const pl=p.poll;if(!pl)return"";const tot=pl.opts.reduce((a,o)=>a+o.n,0),v=pl.mine>=0;return `<div class="poll" id="pl${p.id}">${pl.opts.map((o,i)=>{const pc=tot?Math.round(o.n*100/tot):0;return `<button type="button" class="${pl.mine===i?"on":""}" onclick="votar(${p.id},${i})"><i style="width:${v?pc:0}%"></i><span>${esc(o.t)}</span>${v?`<b>${pc}%</b>`:""}</button>`}).join("")}<small class="m">${tot} ${t(tot===1?"voto":"votos")}</small></div>`};
