function reportar(kind,target,name){if(!U)return login();const R=[["spam","Spam"],["acoso","Acoso o insultos"],["contenido","Contenido inapropiado"],["estafa","Estafa"],["suplantacion","Suplantación"],["otro","Otro"]];
 modal(`<h3>${t("Reportar")}</h3><label for="rpr">${t("Motivo")}</label><select id="rpr" class="vsel">${R.map(x=>`<option value="${x[0]}">${t(x[1])}</option>`).join("")}</select><textarea id="rpn" rows="3" maxlength="300" placeholder="${t("Cuéntanos más (opcional)")}"></textarea><div class="msg" id="rpm"></div><button class="btn p" id="rpg">${t("Enviar reporte")}</button> <button class="btn" onclick="cerrar()">${t("Cancelar")}</button>`);
 $("#rpg").onclick=async()=>{const r=await api("/reports",{method:"POST",body:{kind,target:target||0,name:name||"",reason:$("#rpr").value,note:$("#rpn").value}});if(!r.ok)return $("#rpm").textContent=r.d.error;cerrar();toast(t("Reporte enviado. El staff lo revisará."))}}
async function bloquear(name){if(!confirm(t("¿Bloquear a este jugador? No podrán verse, escribirse ni agregarse.")))return;const r=await api("/blocks/"+encodeURIComponent(name),{method:"POST",body:{}});if(!r.ok)return toast((r.d&&r.d.error)||t("No se pudo cargar"));cerrar();toast(t("Jugador bloqueado"));setTimeout(()=>location.href="/",900)}
async function seguir(name,b){const r=await api("/follow/"+encodeURIComponent(name),{method:"POST",body:{}});if(!r.ok)return toast((r.d&&r.d.error)||t("No se pudo cargar"));b.classList.toggle("p",!r.d.following);b.textContent=t(r.d.following?"Siguiendo":"Seguir");const c=$("#pffo");if(c)c.textContent=cnt(r.d.followers)}
